    """Check the 4-point (LB) property.

    For all positions a < b < c with ac in E and ab not in E,
    there exists d < a with db in E and dc not in E.

    Optimized: for each (a, b) with ab not in E, precompute the set of
    vertices d < a that are adjacent to b.  Then for each c > b with ac in E,
    we need some d in that set with dc not in E.  We track the set of c's
    that are adjacent to all such d's; if any c is not in that set, we have
    a witness.
    """
    for a in range(n):
        va = order[a]
        for b in range(a + 1, n):
            vb = order[b]
            if vb in adj[va]:
                continue
            # ab not in E: collect d < a with db in E
            d_set = []
            for d in range(a):
                vd = order[d]
                if vb in adj[vd]:
                    d_set.append(vd)
            if not d_set:
                # No d < a adjacent to b: any c > b with ac in E is a violation
                for c in range(b + 1, n):
                    vc = order[c]
                    if vc in adj[va]:
                        return False
                continue
            # For each c > b with ac in E, check if some d in d_set has dc not in E
            for c in range(b + 1, n):
                vc = order[c]
                if vc not in adj[va]:
                    continue
                # Need: exists d in d_set with vc not in adj[d]
                found = False
                for vd in d_set:
                    if vc not in adj[vd]:
                        found = True
                        break
                if not found:
                    return False
    return True"}

